#!/usr/bin/env node
/**
 * IM-09 — confirm both hosts' tab icons are the SAME MARK, checked LIVE.
 *
 * The site (`wear-run.help/icon.svg`) and the viewer (`viewer.wear-run.help/favicon.svg`)
 * are two SEPARATE files, generated by two separate scripts
 * (`apps/cms/scripts/gen-icons.mjs`, `apps/viewer/scripts/gen-favicon.mjs`) through two
 * different pipelines — the site's is committed by hand, the viewer's is a sharp
 * rasterise-then-re-embed round trip through `index.html`'s inline data URI. So they can
 * never be byte-identical, and a byte comparison would either always fail (useless) or
 * be dropped entirely (which is how the placeholder mark drifted from the site's real one
 * for eight days, 2026-09-16 to today, with nothing watching). What must hold is that they
 * render the SAME PICTURE.
 *
 * WHY PIXELS, NOT MARKUP. The two files' XML structure differs even when the picture is
 * identical (attribute order, quoting, whether the `prefers-color-scheme` rule survived a
 * round trip) — a text diff would flag cosmetic differences as parity failures. Rendering
 * both to the same fixed-size raster and comparing pixels is robust to exactly that kind
 * of harmless drift while still catching a real one (a different wordmark, a missing
 * path, a colour swap).
 *
 * ⚠️ THE COMPARISON STRIPS `prefers-color-scheme` FROM BOTH SIDES FIRST. A rasteriser does
 * not evaluate media queries at all (no browser environment), so leaving the query in
 * would compare "whatever sharp happens to do with an unmatched query" against itself —
 * not nothing, but not a decision either. Stripping it and comparing the light-mode (ink)
 * rule on both sides is the same reasoning `gen-favicon.mjs`/`gen-icons.mjs` already use
 * when rendering their own raster outputs.
 */
import { createRequire } from 'node:module'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { realpathSync } from 'node:fs'

const HERE = dirname(fileURLToPath(import.meta.url))
const REPO = join(HERE, '..') // this script lives at repo-root scripts/, one hop from the root

/** sharp is the pipeline's dependency, deliberately not this script's own. */
const require = createRequire(join(REPO, 'tools', 'asset-pipeline', 'package.json'))
let sharp
try {
  sharp = require('sharp')
} catch (error) {
  console.error(
    'icon-parity-probe: sharp could not be resolved from tools/asset-pipeline.\n' +
      '  Run `npx --yes pnpm@10.34.5 install --frozen-lockfile` first.\n' +
      `  ${error instanceof Error ? error.message : String(error)}`,
  )
  process.exit(2)
}

export const SITE_ICON_URL = 'https://wear-run.help/icon.svg'
export const VIEWER_ICON_URL = 'https://viewer.wear-run.help/favicon.svg'

/** Square side, in pixels, both marks are rasterised to before comparing. */
export const COMPARE_SIZE = 128
/** A pixel counts as "different" once any RGBA channel differs by more than this. */
export const CHANNEL_TOLERANCE = 24
/** Past this fraction of differing pixels, the two marks are not the same picture. */
export const MAX_DIFFERING_FRACTION = 0.02

/** Pure: Bot Fight Mode's refusal of a robot — inconclusive, never a failed comparison. */
export function isRefusal(status) {
  return status === 403 || status === 429
}

function stripMediaQuery(svg) {
  return svg.replace(/@media[^{]*\{[\s\S]*?\}\s*\}/, '')
}

/**
 * Pure: rasterise both SVG source strings to the same size and compare pixels. No
 * network — the network half lives in fetchMarks() below, kept separate so this can be
 * unit-tested against fixture SVGs instead of a live fetch.
 *
 * @param {string} svgA
 * @param {string} svgB
 * @param {{ size?: number, channelTolerance?: number, maxDifferingFraction?: number }} [options]
 * @returns {Promise<import('./icon-parity-probe.d.mts').IconParityResult>}
 */
export async function compareMarks(
  svgA,
  svgB,
  {
    size = COMPARE_SIZE,
    channelTolerance = CHANNEL_TOLERANCE,
    maxDifferingFraction = MAX_DIFFERING_FRACTION,
  } = {},
) {
  const render = (svg) =>
    sharp(Buffer.from(stripMediaQuery(svg), 'utf8'))
      .resize(size, size, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
      .ensureAlpha()
      .raw()
      .toBuffer()

  const [a, b] = await Promise.all([render(svgA), render(svgB)])
  const totalPixels = size * size
  let differingPixels = 0
  for (let i = 0; i < a.length; i += 4) {
    const dr = Math.abs(a[i] - b[i])
    const dg = Math.abs(a[i + 1] - b[i + 1])
    const db = Math.abs(a[i + 2] - b[i + 2])
    const da = Math.abs(a[i + 3] - b[i + 3])
    if (
      dr > channelTolerance ||
      dg > channelTolerance ||
      db > channelTolerance ||
      da > channelTolerance
    ) {
      differingPixels += 1
    }
  }
  const differingFraction = differingPixels / totalPixels

  return {
    ok: differingFraction <= maxDifferingFraction,
    differingPixels,
    totalPixels,
    differingFraction,
  }
}

/** All network lives here: a plain GET of each host's live SVG. */
async function fetchMarks() {
  const [siteResponse, viewerResponse] = await Promise.all([
    fetch(SITE_ICON_URL),
    fetch(VIEWER_ICON_URL),
  ])
  // Bot Fight Mode refuses datacenter robots intermittently (.github/CLAUDE.md): a 403 or
  // 429 is INCONCLUSIVE, never a failed comparison, or a scheduled run goes red on a
  // healthy site.
  for (const [url, response] of [
    [SITE_ICON_URL, siteResponse],
    [VIEWER_ICON_URL, viewerResponse],
  ]) {
    if (isRefusal(response.status)) return { refused: `${url} answered ${response.status}` }
  }
  if (!siteResponse.ok) {
    throw new Error(`${SITE_ICON_URL} answered ${siteResponse.status}`)
  }
  if (!viewerResponse.ok) {
    throw new Error(`${VIEWER_ICON_URL} answered ${viewerResponse.status}`)
  }
  const [site, viewer] = await Promise.all([siteResponse.text(), viewerResponse.text()])
  return { site, viewer }
}

async function main() {
  const marks = await fetchMarks()
  if (marks.refused) {
    console.log(`::warning::icon-parity-probe: inconclusive — ${marks.refused} (a robot refusal)`)
    return
  }
  const { site, viewer } = marks
  const result = await compareMarks(site, viewer)

  console.log(
    `icon-parity-probe: ${result.differingPixels}/${result.totalPixels} pixels differ ` +
      `(${(result.differingFraction * 100).toFixed(2)}%), ceiling ` +
      `${(MAX_DIFFERING_FRACTION * 100).toFixed(0)}%`,
  )

  if (!result.ok) {
    console.error(
      `icon-parity-probe: ${SITE_ICON_URL} and ${VIEWER_ICON_URL} are showing DIFFERENT marks`,
    )
    process.exit(1)
  }
  console.log('icon-parity-probe: OK — both hosts show the same mark')
}

if (process.argv[1] && import.meta.filename === realpathSync(process.argv[1])) {
  main().catch((error) => {
    console.error(`icon-parity-probe: ${error instanceof Error ? error.message : String(error)}`)
    process.exit(2)
  })
}
